// 触发 CI 流水线(Code 版, 带诊断)
const ctx = $('初始化上下文').first().json;
const ref = 'task/' + ctx.slug;
const token = $env.GITLAB_TOKEN;
const url = $env.GITLAB_API + '/api/v4/projects/' + encodeURIComponent(ctx.repo) + '/pipeline?ref=' + encodeURIComponent(ref);
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url, headers: { 'PRIVATE-TOKEN': token } });
  return [{ json: { pipeline_id: r.id, status: r.status, ref } }];
} catch (e) {
  const body = (e.response && e.response.body) || '';
  throw new Error('触发失败 ref=' + ref + ' url=' + url + ' resp=' + JSON.stringify(body).slice(0, 250));
}

