// OpenHands 完成轮询: 查对话 execution_status
const createResp = $('OpenHands · 创建开发任务').first().json;
const cid = createResp.id;
const key = $env.OPENHANDS_API_KEY;
const base = $env.OPENHANDS_URL || 'http://10.0.0.5:8000';
if (!cid || !/^[0-9a-f-]{36}$/.test(String(cid))) {
  throw new Error('conversation id 非法: ' + JSON.stringify(createResp).slice(0, 200));
}
let status = 'unknown';
for (let i = 0; i < 60; i++) {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/api/conversations/' + cid,
    headers: { 'X-Session-API-Key': key },
  });
  status = r.execution_status || status;
  if (status === 'finished') {
    return [{ json: { conversation_id: cid, finished: true, status } }];
  }
  if (status === 'error' || status === 'paused') {
    throw new Error('OpenHands 状态=' + status + ' cid=' + cid);
  }
  await new Promise(res => setTimeout(res, 15000));
}
throw new Error('OpenHands 900s 未完成(最后状态=' + status + ') cid=' + cid);

// 轮询 CI pipeline 状态直到终态
const ctx = $('初始化上下文').first().json;
const ref = 'task/' + ctx.slug;
const token = $env.GITLAB_TOKEN;
const base = $env.GITLAB_API;
const pid = encodeURIComponent(ctx.repo);
for (let i = 0; i < 60; i++) {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/api/v4/projects/' + pid + '/pipelines?ref=' + encodeURIComponent(ref) + '&per_page=1',
    headers: { 'PRIVATE-TOKEN': token },
  });
  const p = (r && r[0]) || null;
  if (p && ['success', 'failed', 'canceled', 'skipped'].includes(p.status)) {
    if (p.status !== 'success') {
      throw new Error('CI ' + p.status + ' pipeline=' + p.id + ' ref=' + ref + ' — 按 constitution 处理失败分支');
    }
    return [{ json: { pipeline: 'success', pipeline_id: p.id, ref } }];
  }
  await new Promise(res => setTimeout(res, 20000));
}
throw new Error('CI 20 分钟未到终态 ref=' + ref);

// 轮询 QA 报告 MR 直到被合并(门禁C: 人工在 GitLab 审查并点击合并)
const ctx = $('初始化上下文').first().json;
const token = $env.GITLAB_TOKEN;
const base = $env.GITLAB_API;
const pid = encodeURIComponent(ctx.repo);
const branch = 'task/' + ctx.slug;
for (let i = 0; i < 90; i++) {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/api/v4/projects/' + pid + '/merge_requests?source_branch=' + encodeURIComponent(branch) + '&per_page=1',
    headers: { 'PRIVATE-TOKEN': token },
  });
  const mr = (r && r[0]) || null;
  if (mr && mr.state === 'merged') {
    return [{ json: { merged: true, mr_iid: mr.iid } }];
  }
  if (mr && mr.state === 'closed') {
    throw new Error('MR 被关闭(门禁C 拒绝) branch=' + branch);
  }
  await new Promise(res => setTimeout(res, 20000));
}
throw new Error('门禁C 30 分钟无合并决定 branch=' + branch);
